from collections import OrderedDict

class LRUCache:
    def __init__(self, kapasitas): self.kap, self.d = kapasitas, OrderedDict()
    def get(self, k):
        if k not in self.d: return None
        self.d.move_to_end(k); return self.d[k]          # O(1) berkat linked list internal
    def put(self, k, v):
