def saringan(n):
    tanda = [True] * (n + 1); tanda[0] = tanda[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if tanda[i]: tanda[i * i::i] = [False] * len(range(i * i, n + 1, i))
    return [i for i, p in enumerate(tanda) if p]

