kiri, kanan = 0, len(rumah) - 1
while kiri <= kanan:
    tengah = (kiri + kanan) // 2
    if rumah[tengah] == cari:
        print(f"rumah {cari} ada di urutan ke-{tengah + 1}")
        break
    elif rumah[tengah] < cari:
        kiri = tengah + 1
    else:
        kanan = tengah - 1
else:
    print("tidak ditemukan")

