data = list(range(1, 1001))            # 1..1000 terurut
cari = 777

linear = 0
for x in data:
    linear += 1
    if x == cari:
        break

biner = 0
kiri, kanan = 0, len(data) - 1
while kiri <= kanan:
    biner += 1
    t = (kiri + kanan) // 2
    if data[t] == cari:
        break
    elif data[t] < cari:
        kiri = t + 1
    else:
        kanan = t - 1
print(f"linear: {linear} langkah | binary: {biner} langkah")
